INSERT OR IGNORE INTO `places` (`id`, `slug`, `city`, `latitude`, `longitude`, `title_ar`, `title_en`, `description_ar`, `description_en`, `category`, `era`, `source_url`, `source_label_ar`, `source_label_en`, `status`, `created_at`, `updated_at`) VALUES
(1, 'makkah-cave-of-hira', 'makkah', '21.4585', '39.8579', 'غار حراء', 'Cave of Hira', 'الموضع الذي ارتبط ببداية نزول الوحي على النبي محمد ﷺ. نموذج تعريفي قابل للاستبدال بمادتكم العلمية المعتمدة.', 'The site traditionally associated with the beginning of revelation to Prophet Muhammad ﷺ. This sample text can be replaced with your approved research.', 'revelation', 'Beginning of revelation', NULL, 'مادة تجريبية — أضف المصدر المعتمد', 'Sample content — add an approved source', 'published', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000),
(2, 'makkah-jabal-al-nour', 'makkah', '21.4598', '39.8601', 'جبل النور', 'Jabal al-Nour', 'معلم بارز في مكة المكرمة، يشرف على المنطقة المحيطة بغار حراء.', 'A prominent Makkah landmark overlooking the area surrounding the Cave of Hira.', 'mountain', 'Makkah period', NULL, 'مادة تجريبية — أضف المصدر المعتمد', 'Sample content — add an approved source', 'published', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000),
(3, 'madinah-quba-mosque', 'madinah', '24.4398', '39.6176', 'مسجد قباء', 'Quba Mosque', 'من المواقع المركزية في سيرة الهجرة، ويُعرض هنا كنموذج لبطاقة موقع ثنائية اللغة.', 'A central location in the account of the Hijrah, presented here as a bilingual sample place card.', 'mosque', 'Hijrah', NULL, 'مادة تجريبية — أضف المصدر المعتمد', 'Sample content — add an approved source', 'published', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000),
(4, 'madinah-mount-uhud', 'madinah', '24.506', '39.6159', 'جبل أُحد', 'Mount Uhud', 'معلم تاريخي شمال المدينة المنورة، مرتبط بأحداث غزوة أُحد.', 'A historic landmark north of Madinah associated with events of the Battle of Uhud.', 'historic_site', 'Battle of Uhud', NULL, 'مادة تجريبية — أضف المصدر المعتمد', 'Sample content — add an approved source', 'published', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);
